<div class="heading"><div><h1><?= htmlspecialchars($mailbox['email']) ?></h1><p>Connected using IMAP · <?= htmlspecialchars($folder) ?></p></div><a class="button secondary" href="/dashboard">Back to dashboard</a></div>
<?php if(isset($_GET['sent'])): ?><?php if(($_GET['sent_copy']??'1')==='0'): ?><p class="notice">The SMTP server accepted the message, but the Sent-folder copy could not be saved. Do not resend unless you intend to send a duplicate.</p><?php else: ?><p class="notice">Message accepted by the SMTP server and saved to Sent.</p><?php endif; ?><?php if(($_GET['draft_removed']??'1')==='0'): ?><p class="notice">The message was sent, but the original draft could not be removed. It may still appear in Drafts; do not send it again unless you intend to create a duplicate.</p><?php endif; ?><?php endif; ?><?php if(isset($_GET['draft'])): ?><p class="notice">Draft saved to the mail server.</p><?php endif; ?>
<div class="mail-layout"><aside class="mail-sidebar"><a class="button compose-link" href="#compose">Compose</a><h3>Folders</h3><?php foreach($folders as $f): ?><a class="folder-link <?= $folder===$f['path']?'active':'' ?>" href="/mail/<?= (int)$mailbox['id'] ?>?folder=<?= rawurlencode($f['path']) ?>"><?= htmlspecialchars(ucfirst($f['role']==='custom'?$f['name']:$f['role'])) ?></a><?php endforeach; ?><form method="post" action="/mail/<?= (int)$mailbox['id'] ?>/folder" class="folder-create"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><input name="name" maxlength="100" placeholder="New folder" required><button class="small">Create</button></form></aside>
<section class="mail-main"><?php if($message): ?><div class="panel"><div class="message-toolbar"><a href="/mail/<?= (int)$mailbox['id'] ?>?folder=<?= rawurlencode($folder) ?>">← Back to list</a><a href="/mail/<?= (int)$mailbox['id'] ?>?folder=<?= rawurlencode($folder) ?>&reply=<?= (int)$message['uid'] ?>">Reply</a><a href="/mail/<?= (int)$mailbox['id'] ?>?folder=<?= rawurlencode($folder) ?>&forward=<?= (int)$message['uid'] ?>">Forward</a></div><h2><?= htmlspecialchars($message['subject']) ?></h2><p><strong>From:</strong> <?= htmlspecialchars($message['from']) ?><br><strong>To:</strong> <?= htmlspecialchars($message['to']) ?><br><strong>Cc:</strong> <?= htmlspecialchars($message['cc']) ?><br><strong>Date:</strong> <?= htmlspecialchars($message['date']) ?></p><?php if(!empty($message['html'])): ?><iframe class="message-html" sandbox="" referrerpolicy="no-referrer" loading="lazy" title="Email message content" srcdoc="<?= htmlspecialchars($message['html'],ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8') ?>"></iframe><?php else: ?><pre class="message-body"><?= htmlspecialchars($message['body']) ?></pre><?php endif; ?><?php if($message['attachments']): ?><h3>Attachments</h3><?php foreach($message['attachments'] as $a): ?><p><a href="/mail/<?= (int)$mailbox['id'] ?>/download/<?= (int)$message['uid'] ?>?folder=<?= rawurlencode($folder) ?>&part=<?= rawurlencode($a['part']) ?>"><?= htmlspecialchars($a['name']) ?></a> <small><?= number_format($a['size']/1024,1) ?> KB</small></p><?php endforeach; ?><?php endif; ?></div><?php else: ?>
<div class="panel"><form method="get" action="/mail/<?= (int)$mailbox['id'] ?>" class="search-form"><input type="hidden" name="folder" value="<?= htmlspecialchars($folder) ?>"><input name="q" value="<?= htmlspecialchars((string)($_GET['q']??'')) ?>" placeholder="Search this folder"><button>Search</button></form><p class="muted"><?= (int)$listing['total'] ?> messages · Page <?= (int)$listing['page'] ?> / <?= max(1,(int)$listing['pages']) ?></p>
<?php if(!$listing['messages']): ?><p>No messages found in this folder.</p><?php else: ?><div class="message-list"><?php foreach($listing['messages'] as $m): ?><article class="message-row <?= $m['seen']?'':'unread' ?>"><div class="message-info"><a href="/mail/<?= (int)$mailbox['id'] ?>/message/<?= (int)$m['uid'] ?>?folder=<?= rawurlencode($folder) ?>"><span class="star"><?= $m['flagged']?'★':'☆' ?></span><strong><?= htmlspecialchars($m['from']) ?></strong><span><?= htmlspecialchars($m['subject']?:'(no subject)') ?></span></a><small><?= htmlspecialchars($m['date']) ?> · <?= number_format($m['size']/1024,1) ?> KB</small></div><div class="row-actions"><?php if(array_filter($folders,fn($f)=>$f['path']===$folder&&$f['role']==='drafts')): ?><a class="button small secondary" href="/mail/<?= (int)$mailbox['id'] ?>?folder=<?= rawurlencode($folder) ?>&edit_draft=<?= (int)$m['uid'] ?>">Edit draft</a><?php endif; ?><form method="post" action="/mail/<?= (int)$mailbox['id'] ?>/action"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><input type="hidden" name="folder" value="<?= htmlspecialchars($folder) ?>"><input type="hidden" name="uid" value="<?= (int)$m['uid'] ?>"><input type="hidden" name="action" value="<?= $m['flagged']?'unstar':'star' ?>"><button title="Toggle star"><?= $m['flagged']?'★':'☆' ?></button></form><form method="post" action="/mail/<?= (int)$mailbox['id'] ?>/action"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><input type="hidden" name="folder" value="<?= htmlspecialchars($folder) ?>"><input type="hidden" name="uid" value="<?= (int)$m['uid'] ?>"><input type="hidden" name="action" value="<?= $m['seen']?'unread':'read' ?>"><button><?= $m['seen']?'Mark unread':'Mark read' ?></button></form><form method="post" action="/mail/<?= (int)$mailbox['id'] ?>/action"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><input type="hidden" name="folder" value="<?= htmlspecialchars($folder) ?>"><input type="hidden" name="uid" value="<?= (int)$m['uid'] ?>"><input type="hidden" name="action" value="move"><select name="destination" aria-label="Move to folder"><?php foreach($folders as $dest): if($dest['path']!==$folder): ?><option value="<?= htmlspecialchars($dest['path']) ?>"><?= htmlspecialchars($dest['name']) ?></option><?php endif; endforeach; ?></select><button>Move</button></form><form method="post" action="/mail/<?= (int)$mailbox['id'] ?>/action" data-confirm="Delete this message?"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><input type="hidden" name="folder" value="<?= htmlspecialchars($folder) ?>"><input type="hidden" name="uid" value="<?= (int)$m['uid'] ?>"><input type="hidden" name="action" value="delete"><button class="danger">Delete</button></form></div></article><?php endforeach; ?></div><?php endif; ?>
<div class="pagination"><?php if($listing['page']>1): ?><a href="?folder=<?= rawurlencode($folder) ?>&page=<?= $listing['page']-1 ?>&q=<?= rawurlencode((string)($_GET['q']??'')) ?>">Previous</a><?php endif; ?><?php if($listing['page']<$listing['pages']): ?><a href="?folder=<?= rawurlencode($folder) ?>&page=<?= $listing['page']+1 ?>&q=<?= rawurlencode((string)($_GET['q']??'')) ?>">Next</a><?php endif; ?></div></div><?php endif; ?>
<section class="panel" id="compose"><h2>Compose message</h2><form method="post" enctype="multipart/form-data" action="/mail/<?= (int)$mailbox['id'] ?>/send"><input type="hidden" name="folder" value="<?= htmlspecialchars($folder) ?>"><input type="hidden" name="draft_uid" value="<?= (int)($compose['draft_uid']??0) ?>"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><label>To<input type="text" name="to" value="<?= htmlspecialchars($compose['to']) ?>" placeholder="name@example.com"></label><div class="grid"><label>CC<input type="text" name="cc" value="<?= htmlspecialchars($compose['cc']) ?>"></label><label>BCC<input type="text" name="bcc" value="<?= htmlspecialchars($compose['bcc']) ?>"></label></div><label>Subject<input name="subject" maxlength="998" value="<?= htmlspecialchars($compose['subject']) ?>"></label><label>Message<textarea name="body" rows="9"><?= htmlspecialchars($compose['body']) ?></textarea></label><?php if(!empty($compose['attachments'])): ?><div class="retained-attachments"><strong>Existing attachments (kept when saving or sending this draft)</strong><?php foreach($compose['attachments'] as $a): ?><span><?= htmlspecialchars($a['name']) ?> · <?= number_format(($a['size']??0)/1024,1) ?> KB</span><?php endforeach; ?></div><?php endif; ?><label>Attachments (max 5 new files; existing draft attachments are preserved)<input type="file" name="attachments[]" multiple></label><button type="submit" name="mode" value="send">Send message</button> <button class="secondary" type="submit" name="mode" value="draft" formnovalidate>Save draft</button></form></section>
</section></div>
